#!/usr/bin/env python3
"""FS3 v163 - the Shivan cycle opens: fleet tabs, M61, the Dante.

    Cycle 3   from wave 61 both fleets serve. The player starts in a
              Myrmidon; Terran and Vasudan hulls unlock side by side, each
              down its own list, counted from the start of the cycle.
    Hangar    two tabs, TERRAN and VASUDAN. A tab is open while an allied
              destroyer of that fleet is on the field, the other is greyed
              out; both with destroyers of both fleets (or the Colossus).
              No allied destroyer: no ship switch at all.
    Support   the same two tabs, same rule; with no allied destroyer on the
              field both are open. Tab or the arrow keys switch tabs.
    Dante     opens with the Shivan cycle (mission 61), not before.
    M61       The Reconnaissance: at the Knossos. Shivans come THROUGH the
              portal in its turquoise vortex; the Aeolus covers the field.
              A destroyed Rakshasa is replaced, the enemy escalates every
              30 s, at 150 s a Shivan destroyer comes through. The mission
              ends when the Aeolus is lost (-900), then the Shivans jump
              out.
    Missions  new: portalIn (arrivals through the Knossos), guard on an
              allied ship, events 'mehr' (escalate) and 'abzug' (withdraw).

Needs v162. Edits src/30_waves.js, src/40_world.js, src/60_effects.js and
src/70_ui.js in place, and writes the updated fieldsim.js, shipsim.js,
callsim.js, pausesim.js, hudsim.js, wpnsim.js and swtest.js. Run
assemble.py afterwards.
"""
import base64
import os
import sys

if "IMPACT_CAP_HULL" not in open("src/50_combat.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v162 einspielen.")
if "FLEET_TABS" in open("src/70_ui.js", encoding="utf-8").read():
    sys.exit("Abbruch: v163 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)

